import { FeatureCatalog } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertThrows(action: () => void, message: string): void {
  try {
    action();
  } catch (error: unknown) {
    assert(error instanceof Error && error.message === message, `expected Error(${message})`);
    return;
  }
  throw new Error(`expected Error(${message})`);
}

const catalog = new FeatureCatalog();
assert(catalog.snapshot().length === 0, "a new catalog should be empty");

catalog.insert("  beta  ", "initial note");
catalog.insert("Alpha", undefined, false);
catalog.insert("Zeta");
assert(JSON.stringify(catalog.snapshot()) === JSON.stringify([
  { code: "Alpha", active: false },
  { code: "Zeta", active: true },
  { code: "beta", note: "initial note", active: true },
]), "insert defaults, normalization, and ordinary code sorting were incorrect");

catalog.amend(" beta ", { active: false });
assert(catalog.snapshot()[2].note === "initial note" && catalog.snapshot()[2].active === false, "amend should retain absent fields and apply false");
catalog.amend("Alpha", { note: "documented" });
assert(catalog.snapshot()[0].note === "documented" && catalog.snapshot()[0].active === false, "amend should update only supplied fields");

const firstSnapshot = catalog.snapshot();
const secondSnapshot = catalog.snapshot();
assert(firstSnapshot !== secondSnapshot && firstSnapshot[0] !== secondSnapshot[0], "snapshots and their entries must be copies");
firstSnapshot[0].code = "mutated";
firstSnapshot[0].active = true;
firstSnapshot.pop();
assert(catalog.snapshot().length === 3 && catalog.snapshot()[0].code === "Alpha" && catalog.snapshot()[0].active === false, "snapshot mutation must not affect catalog state");

assertThrows(() => catalog.insert("beta"), "Feature already exists");
assertThrows(() => catalog.insert(" \n "), "Feature code must not be empty");
assertThrows(() => catalog.amend("missing", { active: true }), "Feature not found");
assertThrows(() => catalog.drop(" missing "), "Feature not found");
assert(catalog.snapshot().length === 3, "invalid operations must leave state unchanged");

catalog.drop(" Zeta ");
assert(catalog.snapshot().map((feature) => feature.code).join(",") === "Alpha,beta", "drop should normalize and remove the requested code");

